const PR28=[{label:"Ví dụ: Chặt nhị phân X, mỗi lần BFS",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint N = 3;\nvector<vector<int>> hgt = {{1, 5, 9}, {2, 3, 8}, {7, 4, 6}};\n\nbool diDuoc(int X) {                    // BFS chỉ qua bước có chênh lệch <= X\n    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\n    vector<vector<bool>> tham(N, vector<bool>(N, false));\n    queue<pair<int, int>> q;\n    tham[0][0] = true;\n    q.push({0, 0});\n    while (!q.empty()) {\n        int r = q.front().first, c = q.front().second;\n        q.pop();\n        for (int k = 0; k < 4; k++) {\n            int nr = r + dx[k], nc = c + dy[k];\n            if (nr < 0 || nr >= N || nc < 0 || nc >= N || tham[nr][nc]) continue;\n            if (abs(hgt[nr][nc] - hgt[r][c]) > X) continue;\n            tham[nr][nc] = true;\n            q.push({nr, nc});\n        }\n    }\n    return tham[N - 1][N - 1];\n}\n\nint main() {\n    int lo = 0, hi = 9;                 // đáp án trong [0, max độ cao]\n    while (lo < hi) {\n        int mid = (lo + hi) / 2;\n        if (diDuoc(mid)) hi = mid;      // đi được: thử X nhỏ hơn\n        else lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["lo","hi","mid"]}]},{label:"Ví dụ: BFS trên đồ thị đảo chiều",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint n = 4;\nvector<vector<int>> ke(5), keNguoc(5);\n\nvector<int> bfs(vector<vector<int>>& g, int s) {\n    vector<int> d(n + 1, -1);\n    queue<int> q;\n    d[s] = 0;\n    q.push(s);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : g[u]) if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }\n    }\n    return d;\n}\n\nint main() {\n    int canh[3][2] = {{1, 2}, {2, 3}, {4, 3}};   // đường một chiều u -> v\n    for (auto& e : canh) { ke[e[0]].push_back(e[1]); keNguoc[e[1]].push_back(e[0]); }\n    vector<int> dS = bfs(ke, 1), dT = bfs(keNguoc, 4);   // dT[v]: từ v tới 4\n    // đề xuất đường hai chiều (3, 4): đi 1 -> ... -> 3 rồi sang 4\n    int u = 3, v = 4, tot = -1;\n    if (dS[u] != -1 && dT[v] != -1) tot = dS[u] + 1 + dT[v];\n    if (dS[v] != -1 && dT[u] != -1 && (tot == -1 || dS[v] + 1 + dT[u] < tot)) tot = dS[v] + 1 + dT[u];\n    cout << dS[4] << \" \" << tot << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dS"},{type:"cells",of:"dT"}]},{label:"Ví dụ: Đếm tam giác bằng tìm kiếm nhị phân",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {3, 4, 5, 6, 7};\n    sort(a.begin(), a.end());\n    int n = a.size();\n    long long nhon = 0, vuong = 0, tu = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = i + 1; j < n; j++) {\n            long long s = a[i] * a[i] + a[j] * a[j];\n            int L = j + 1;                                        // c > b\n            int R = lower_bound(a.begin(), a.end(), a[i] + a[j]) - a.begin();   // c < a + b\n            if (L >= R) continue;\n            int lo = L, hi = R;             // p: đầu tiên có c * c >= s\n            while (lo < hi) { int mid = (lo + hi) / 2; if (a[mid] * a[mid] >= s) hi = mid; else lo = mid + 1; }\n            int p = lo;\n            lo = p; hi = R;                 // q: đầu tiên có c * c > s\n            while (lo < hi) { int mid = (lo + hi) / 2; if (a[mid] * a[mid] > s) hi = mid; else lo = mid + 1; }\n            int q = lo;\n            nhon += p - L; vuong += q - p; tu += R - q;\n        }\n    cout << nhon << \" \" << vuong << \" \" << tu << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","j"]},{type:"vars",names:["nhon","vuong","tu"]}]}];
