makeEx2(document.getElementById("ex-l28"),sim28,[{t:"Leo núi",d:"File LEONUI.INP: dòng 1 là N (1 ≤ N ≤ 500); N dòng sau mỗi dòng N số nguyên trong [0, 10⁹]: độ cao các ô. Đi từ ô (1, 1) tới ô (N, N), mỗi bước sang ô chung cạnh với độ chênh độ cao không quá X. Ghi vào LEONUI.OUT giá trị X nhỏ nhất để đi được.",tests:[{in:"3\n1 5 9\n2 3 8\n7 4 6",out:"2"},{in:"1\n7",out:"0"},{in:"2\n0 1000000000\n1000000000 0",out:"1000000000"},{in:"8\n14 95 16 69 76 91 22 28\n16 81 59 97 53 26 27 18\n50 20 16 77 24 25 3 52\n30 8 12 53 40 89 16 22\n64 66 88 92 84 34 78 29\n86 57 16 25 1 98 36 81\n86 33 10 66 68 35 92 15\n73 53 21 25 47 8 4 54",out:"50"},{in:"10\n820060942 897374912 865945315 524160627 401202544 171271639 405370819 856246604 276492207 898257079\n414698694 942465441 541547764 711240863 720312969 187854185 247243131 185074723 331440748 823884480\n630469984 203747271 804667959 739319880 574846083 452085293 33344134 238487784 212249908 65930919\n980693779 346136666 385274796 724389872 743909322 817787889 962290741 427972173 114131760 535932140\n875113889 923609744 159968687 780628136 535292400 559370068 221245496 584826750 848833801 481298139\n610381630 457980866 171010815 720513622 447984272 261579002 499882060 929326328 989257893 316065206\n502084868 248382970 253465645 35827761 16225116 467615667 437131172 738130032 593318158 270940681\n472290161 147684144 890674108 912973369 723192481 560297178 541447483 989613834 3819681 696114460\n488698505 392431687 723959125 386356728 91588838 235782195 433567814 210937697 597690045 110193687\n664650967 141051771 127068016 722090251 692603144 318115640 935224258 548524071 651674769 700704287",out:"337586374"},{in:"15\n457 73 156 778 782 198 174 824 533 909 89 461 518 327 969\n518 493 921 754 815 733 400 410 783 409 867 713 70 337 247\n808 543 350 589 589 955 532 383 537 90 861 341 911 799 96\n659 790 406 297 401 875 472 981 869 139 753 758 93 409 249\n925 63 136 311 493 847 991 641 207 22 690 768 158 631 590\n487 31 475 17 247 72 125 897 418 37 59 738 832 273 495\n858 350 334 402 364 212 792 35 991 807 790 904 814 359 706\n589 779 889 197 25 338 520 118 122 381 76 64 618 206 582\n163 558 262 698 462 413 651 853 508 967 756 528 968 187 226\n839 367 397 598 257 209 397 39 280 850 510 522 229 381 322\n662 292 283 592 380 527 152 947 438 325 35 563 335 895 715\n803 225 675 327 599 399 883 169 340 973 548 164 380 901 615\n506 3 720 391 1000 5 35 543 325 542 127 504 318 840 257\n785 675 609 857 834 265 418 279 120 397 84 488 165 959 64\n463 861 755 300 339 700 857 784 537 246 922 466 795 643 184",out:"377"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint N;\nvector<vector<long long>> hgt;\n\nbool diDuoc(long long X) {\n    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\n    vector<vector<bool>> tham(N, vector<bool>(N, false));\n    queue<pair<int, int>> q;\n    tham[0][0] = true;\n    q.push({0, 0});\n    while (!q.empty()) {\n        int r = q.front().first, c = q.front().second;\n        q.pop();\n        for (int k = 0; k < 4; k++) {\n            int nr = r + dx[k], nc = c + dy[k];\n            if (nr < 0 || nr >= N || nc < 0 || nc >= N || tham[nr][nc]) continue;\n            if (abs(hgt[nr][nc] - hgt[r][c]) > X) continue;\n            tham[nr][nc] = true;\n            q.push({nr, nc});\n        }\n    }\n    return tham[N - 1][N - 1];\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"LEONUI.INP\", \"r\")) {\n        freopen(\"LEONUI.INP\", \"r\", stdin);\n        freopen(\"LEONUI.OUT\", \"w\", stdout);\n    }\n    cin >> N;\n    hgt.assign(N, vector<long long>(N));\n    for (auto& r : hgt) for (auto& x : r) cin >> x;\n    long long X = 0;\n    while (!diDuoc(X)) X++;             // thử X = 0, 1, 2, ...: chậm khi độ cao lớn\n    cout << X << \"\\n\";\n    return 0;\n}",file:"LEONUI"},{t:"Đề xuất làm đường",d:"File DEXUAT.INP: dòng 1 là n, m, q, S, T (2 ≤ n ≤ 10⁵, 0 ≤ m, 1 ≤ q ≤ 10⁵); m dòng tiếp mỗi dòng u v: đường một chiều từ u tới v; q dòng tiếp mỗi dòng u v: một đề xuất làm đường hai chiều giữa u và v. Chỉ được chọn tối đa một đề xuất. Ghi vào DEXUAT.OUT độ dài (số con đường) ngắn nhất từ S tới T có thể đạt được, hoặc −1.",tests:[{in:"4 3 2 1 4\n1 2\n2 3\n4 3\n3 4\n1 3",out:"3"},{in:"2 0 1 1 2\n1 2",out:"1"},{in:"3 2 1 1 3\n1 2\n2 3\n1 3",out:"1"},{in:"3 0 1 1 3\n1 2",out:"-1"},{in:"30 50 20 1 30\n15 9\n20 13\n3 17\n28 14\n16 13\n26 18\n20 9\n7 4\n4 14\n15 25\n7 7\n20 30\n6 9\n9 19\n5 8\n24 2\n21 10\n20 8\n17 6\n8 30\n26 16\n28 13\n25 25\n29 14\n11 24\n21 19\n20 8\n3 28\n26 10\n12 14\n28 1\n9 13\n29 4\n13 9\n26 27\n22 6\n2 24\n8 10\n16 21\n8 27\n2 8\n1 5\n5 30\n7 11\n30 25\n13 9\n4 4\n30 18\n8 27\n27 4\n7 19\n27 24\n2 28\n11 14\n1 27\n28 2\n10 9\n19 23\n26 17\n9 27\n23 16\n21 22\n19 13\n9 23\n12 28\n18 27\n16 5\n9 23\n29 3\n11 9",out:"2"},{in:"50 70 30 5 9\n2 4\n41 7\n5 42\n49 10\n27 35\n11 1\n29 20\n13 1\n25 36\n23 14\n22 25\n35 20\n47 23\n14 7\n21 40\n21 49\n35 3\n45 42\n35 2\n1 44\n45 4\n36 33\n45 41\n42 36\n12 26\n34 44\n36 6\n2 17\n41 29\n25 26\n36 50\n45 35\n15 8\n6 25\n7 23\n45 42\n9 25\n22 3\n5 46\n50 7\n4 7\n41 10\n40 44\n19 8\n33 50\n43 42\n16 44\n26 32\n45 28\n46 38\n44 7\n48 22\n10 17\n10 45\n14 18\n27 10\n1 13\n17 8\n22 35\n18 4\n19 19\n7 6\n8 13\n34 43\n9 49\n38 1\n31 2\n38 42\n23 21\n1 40\n34 14\n9 27\n11 8\n31 37\n21 37\n49 43\n22 8\n3 30\n36 50\n6 49\n11 2\n5 23\n2 34\n3 24\n20 7\n6 45\n1 7\n31 12\n25 34\n11 38\n26 9\n19 1\n5 1\n50 5\n23 15\n33 10\n8 49\n4 37\n27 40\n27 18",out:"6"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DEXUAT.INP\", \"r\")) {\n        freopen(\"DEXUAT.INP\", \"r\", stdin);\n        freopen(\"DEXUAT.OUT\", \"w\", stdout);\n    }\n    int n, m, q, S, T;\n    cin >> n >> m >> q >> S >> T;\n    vector<vector<int>> ke(n + 1);\n    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; ke[u].push_back(v); }\n    int tot = -1;\n    for (int k = 0; k <= q; k++) {          // k = 0: không thêm; mỗi đề xuất BFS lại từ đầu\n        int u = 0, v = 0;\n        if (k > 0) { cin >> u >> v; ke[u].push_back(v); ke[v].push_back(u); }\n        vector<int> d(n + 1, -1);\n        queue<int> qu;\n        d[S] = 0; qu.push(S);\n        while (!qu.empty()) {\n            int x = qu.front(); qu.pop();\n            for (int y : ke[x]) if (d[y] == -1) { d[y] = d[x] + 1; qu.push(y); }\n        }\n        if (d[T] != -1 && (tot == -1 || d[T] < tot)) tot = d[T];\n        if (k > 0) { ke[u].pop_back(); ke[v].pop_back(); }\n    }\n    cout << tot << \"\\n\";\n    return 0;\n}",file:"DEXUAT",perf:{gen:n=>{const e=[],p=[];for(let i=1;i<n;i++)e.push(i+" "+(i+1));for(let i=0;i<n;i++)p.push((1+(i*7)%n)+" "+(1+(i*13)%n));return n+" "+(n-1)+" "+n+" 1 "+n+"\n"+e.join("\n")+"\n"+p.join("\n")},ns:[100,200,400],need:"n",limit:n=>150*n+3000,why:"BFS lại cho mỗi đề xuất là O(q · (n + m)); hai lần BFS rồi O(1) mỗi đề xuất là O(n + m + q)."}},{t:"Tam giác",d:"File TAMGIAC.INP: dòng 1 là N (3 ≤ N ≤ 5000); dòng 2 là N số nguyên dương khác nhau (≤ 10⁹): độ dài các que. Ghi vào TAMGIAC.OUT ba số: số tam giác nhọn, số tam giác vuông, số tam giác tù tạo được bằng ba que khác nhau. Subtask 25%: N ≤ 300.",tests:[{in:"5\n3 4 5 6 7",out:"3 1 5"},{in:"3\n1 2 3",out:"0 0 0"},{in:"3\n5 12 13",out:"0 1 0"},{in:"3\n1000000000 999999999 999999998",out:"1 0 0"},{in:"25\n35 49 42 18 16 13 2 22 28 19 52 17 10 12 4 37 50 5 24 47 15 39 46 29 8",out:"324 3 625"},{in:"30\n933201367 242221051 384746488 3029106 681888783 711082033 136732608 297351934 325749363 318450457 545138126 201577690 946615413 400971098 11423705 335362982 525298294 468361861 549281157 629058116 771594425 31067498 369107214 334431546 203259767 658577953 946908046 398939587 70219505 614044040",out:"671 0 1126"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TAMGIAC.INP\", \"r\")) {\n        freopen(\"TAMGIAC.INP\", \"r\", stdin);\n        freopen(\"TAMGIAC.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long nhon = 0, vuong = 0, tu = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = i + 1; j < n; j++)\n            for (int k = j + 1; k < n; k++) {\n                if (a[k] >= a[i] + a[j]) break;\n                long long s = a[i] * a[i] + a[j] * a[j], c = a[k] * a[k];\n                if (c < s) nhon++;\n                else if (c == s) vuong++;\n                else tu++;\n            }\n    cout << nhon << \" \" << vuong << \" \" << tu << \"\\n\";\n    return 0;\n}",file:"TAMGIAC",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>1000000+i*7).join(" "),ns:[30,60,120],need:"n2",limit:n=>400*n*n+5000,why:"Ba vòng lặp là O(N³); mỗi cặp hai lần tìm kiếm nhị phân là O(N² log N)."}}]);

makeQuiz("quiz28","score28",[{"q": "Bài Tìm đường (TP.HCM 2021) dùng được tìm kiếm nhị phân vì:", "o": ["Bảng đã sắp xếp", "Đi được với X thì đi được với mọi X lớn hơn", "N nhỏ", "Độ cao khác nhau"], "a": 1, "e": "Hàm kiểm tra đơn điệu."}, {"q": "Khoảng cách từ mọi đỉnh tới T trên đồ thị có hướng tính bằng:", "o": ["BFS từ T trên đồ thị gốc", "BFS từ S", "DFS từ mọi đỉnh", "BFS từ T trên đồ thị đảo chiều"], "a": 3, "e": "Đảo chiều mọi cạnh."}, {"q": "Đề xuất cạnh hai chiều (u, v) cho đường S → T dài:", "o": ["dS[u] + dS[v]", "min(dS[u] + 1 + dT[v], dS[v] + 1 + dT[u])", "dT[u] + dT[v]", "dS[T] + 1"], "a": 1, "e": "Đi tới một đầu, qua cạnh mới, rồi từ đầu kia tới T."}, {"q": "Ba que 5, 12, 13 tạo tam giác:", "o": ["Nhọn", "Tù", "Không tạo được", "Vuông"], "a": 3, "e": "5² + 12² = 13²."}, {"q": "Đếm tam giác với N = 5000 cần độ phức tạp khoảng:", "o": ["O(N³)", "O(N² log N)", "O(2ᴺ)", "O(N!)"], "a": 1, "e": "N³ = 1,25·10¹¹ quá chậm."}]);

